<?php get_header(); ?><main id="contenu"><?php while (have_posts()) : the_post(); $slug = get_post_field('post_name', get_the_ID()); $file = get_template_directory() . '/content-' . $slug . '.php'; if (is_file($file) && in_array($slug, ['recits','evenements','a-propos','la-lettre','publications','lidentite-libanaise-en-danger-2e-session'], true)) { include $file; } else { ?><div class="container wp-page-body"><h1 class="section-title"><?php the_title(); ?></h1><?php the_content(); ?></div><?php } endwhile; ?></main><?php get_footer(); ?>
